SELECT d.ControlNumber, 'RC' AS TxType, h.RefNumber AS TxNumber, h.SecondDate AS DateOfEntry, h.SecondDate AS DateOfCreation, h.TxNumber AS RefNumber, h.TrackingNumber, h.CustomerID, h.SupplierCode, h.DateOfEntry AS SecondDate, h.Particulars, h.TotalCost, h.TotalSale, h.TaxA, h.TaxB, h.TaxC, h.OtherCharges, h.GrossSale, h.SalesDiscount, h.TotalAmount, h.TotalQty, h.ThisPaid AS PreviousPaid, (h.TotalAmount-h.ThisPaid) AS ThisPaid, h.Change, h.PrintCounter, IIf(IsNull(p.TxNumber),0,p.Counts) AS PaymentLink, h.SalesPersonLink, 0 AS Status
FROM (fixMissedTxHeader_TxDetails AS d INNER JOIN TxHeader AS h ON d.TxNumber = h.RefNumber) LEFT JOIN fixMissedTxHeader_TxPayment AS p ON h.RefNumber = p.TxNumber;
